const html="<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"utf-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n    <title>Hone - Jiu-Jitsu Skill Acquisition App Brief</title>\n    <style>\n      :root {\n        color-scheme: light;\n        --ink: #1b1f23;\n        --muted: #59636e;\n        --quiet: #7a858f;\n        --paper: #fbfaf7;\n        --panel: #ffffff;\n        --line: #d9dedf;\n        --line-strong: #aeb9bc;\n        --sage: #5f766d;\n        --sage-dark: #374d46;\n        --clay: #a35d43;\n        --gold: #b78b2f;\n        --blue: #476b86;\n        --violet: #665f8f;\n        --green-soft: #e6eee8;\n        --clay-soft: #f2e4dc;\n        --gold-soft: #f3ead4;\n        --blue-soft: #dfeaf0;\n        --violet-soft: #e6e3ef;\n        --shadow: 0 18px 46px rgba(31, 42, 46, 0.12);\n        --radius: 8px;\n        --max: 1160px;\n      }\n\n      * {\n        box-sizing: border-box;\n      }\n\n      html {\n        scroll-behavior: smooth;\n      }\n\n      body {\n        margin: 0;\n        color: var(--ink);\n        background:\n          linear-gradient(180deg, rgba(232, 237, 235, 0.65), rgba(251, 250, 247, 0) 420px),\n          var(--paper);\n        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, \"Segoe UI\", sans-serif;\n        font-weight: 300;\n        line-height: 1.5;\n      }\n\n      a {\n        color: inherit;\n      }\n\n      .shell {\n        width: min(var(--max), calc(100% - 40px));\n        margin: 0 auto;\n      }\n\n      .topbar {\n        position: sticky;\n        top: 0;\n        z-index: 10;\n        backdrop-filter: blur(18px);\n        background: rgba(251, 250, 247, 0.82);\n        border-bottom: 1px solid rgba(174, 185, 188, 0.45);\n      }\n\n      .topbar-inner {\n        display: flex;\n        align-items: center;\n        justify-content: space-between;\n        min-height: 64px;\n        gap: 20px;\n      }\n\n      .brand {\n        display: flex;\n        align-items: center;\n        gap: 12px;\n        font-weight: 750;\n        letter-spacing: 0;\n      }\n\n      .mark {\n        display: grid;\n        place-items: center;\n        width: 34px;\n        height: 34px;\n        border-radius: 8px;\n        background: var(--sage-dark);\n        color: #fff;\n        font-size: 18px;\n        font-weight: 800;\n      }\n\n      .nav {\n        display: flex;\n        gap: 18px;\n        color: var(--muted);\n        font-size: 14px;\n      }\n\n      .nav a {\n        text-decoration: none;\n      }\n\n      .nav a:hover {\n        color: var(--ink);\n      }\n\n      .hero {\n        padding: 72px 0 44px;\n      }\n\n      .hero-grid {\n        display: grid;\n        grid-template-columns: minmax(0, 1.04fr) minmax(320px, 0.96fr);\n        gap: 42px;\n        align-items: center;\n      }\n\n      .hero-grid > *,\n      .section-head > *,\n      .split > * {\n        min-width: 0;\n      }\n\n      .eyebrow {\n        display: inline-flex;\n        align-items: center;\n        gap: 8px;\n        color: var(--sage-dark);\n        font-size: 13px;\n        font-weight: 750;\n        text-transform: uppercase;\n        letter-spacing: 0.08em;\n      }\n\n      .eyebrow::before {\n        content: \"\";\n        width: 28px;\n        height: 2px;\n        background: var(--clay);\n      }\n\n      h1,\n      h2,\n      h3 {\n        font-weight: 800;\n      }\n\n      h1,\n      h2,\n      h3,\n      p {\n        margin-top: 0;\n      }\n\n      p,\n      li {\n        font-weight: 300;\n      }\n\n      h1 {\n        max-width: 780px;\n        margin-bottom: 22px;\n        font-size: clamp(44px, 6vw, 80px);\n        line-height: 0.98;\n        letter-spacing: 0;\n      }\n\n      .nowrap {\n        white-space: nowrap;\n      }\n\n      .hero-copy {\n        max-width: 720px;\n        margin-bottom: 26px;\n        color: var(--muted);\n        font-size: 20px;\n        font-weight: 300;\n        line-height: 1.55;\n      }\n\n      .hero-actions {\n        display: flex;\n        flex-wrap: wrap;\n        gap: 12px;\n        align-items: center;\n      }\n\n      .button {\n        display: inline-flex;\n        align-items: center;\n        justify-content: center;\n        min-height: 44px;\n        padding: 0 18px;\n        border: 1px solid var(--sage-dark);\n        border-radius: 8px;\n        background: var(--sage-dark);\n        color: #fff;\n        font-weight: 740;\n        text-decoration: none;\n      }\n\n      .button.secondary {\n        background: transparent;\n        color: var(--sage-dark);\n      }\n\n      .phone {\n        width: min(100%, 420px);\n        margin-left: auto;\n        border: 1px solid #20282b;\n        border-radius: 34px;\n        background: #111719;\n        padding: 14px;\n        box-shadow: var(--shadow);\n      }\n\n      .phone-screen {\n        overflow: hidden;\n        border-radius: 24px;\n        background: #f7f6f2;\n        min-height: 640px;\n        border: 1px solid #30383b;\n      }\n\n      .phone-status {\n        height: 34px;\n        background: #f7f6f2;\n      }\n\n      .app-head {\n        display: flex;\n        justify-content: space-between;\n        align-items: center;\n        padding: 8px 18px 16px;\n      }\n\n      .app-title {\n        font-size: 26px;\n        font-weight: 800;\n      }\n\n      .focus-pill {\n        padding: 6px 10px;\n        border-radius: 999px;\n        background: var(--gold-soft);\n        color: #6b4a05;\n        font-size: 12px;\n        font-weight: 760;\n      }\n\n      .phone-section {\n        padding: 0 18px 18px;\n      }\n\n      .mini-label {\n        margin-bottom: 8px;\n        color: var(--quiet);\n        font-size: 12px;\n        font-weight: 780;\n        text-transform: uppercase;\n        letter-spacing: 0.08em;\n      }\n\n      .skill-card {\n        border: 1px solid var(--line);\n        border-radius: 8px;\n        background: #fff;\n        padding: 14px;\n        margin-bottom: 10px;\n      }\n\n      .skill-card strong {\n        display: block;\n        margin-bottom: 6px;\n      }\n\n      .skill-meta {\n        display: grid;\n        grid-template-columns: repeat(3, minmax(0, 1fr));\n        gap: 8px;\n        margin-top: 12px;\n      }\n\n      .metric {\n        border-radius: 8px;\n        background: #f0f2ef;\n        padding: 8px;\n      }\n\n      .metric span {\n        display: block;\n        color: var(--quiet);\n        font-size: 11px;\n      }\n\n      .metric b {\n        font-size: 17px;\n      }\n\n      .quick-log {\n        display: grid;\n        grid-template-columns: repeat(2, minmax(0, 1fr));\n        gap: 9px;\n      }\n\n      .quick-log div {\n        min-height: 54px;\n        border: 1px solid var(--line);\n        border-radius: 8px;\n        background: #fff;\n        display: flex;\n        align-items: center;\n        justify-content: center;\n        padding: 8px;\n        text-align: center;\n        font-size: 13px;\n        font-weight: 760;\n      }\n\n      section {\n        padding: 64px 0;\n      }\n\n      .section-head {\n        display: grid;\n        grid-template-columns: minmax(0, 0.78fr) minmax(280px, 0.48fr);\n        gap: 36px;\n        align-items: end;\n        margin-bottom: 30px;\n      }\n\n      h2 {\n        margin-bottom: 12px;\n        font-size: clamp(30px, 4vw, 48px);\n        line-height: 1.05;\n        letter-spacing: 0;\n      }\n\n      .section-head p,\n      .lead {\n        color: var(--muted);\n        font-size: 18px;\n        font-weight: 300;\n      }\n\n      .band {\n        background: #eef2ef;\n        border-top: 1px solid var(--line);\n        border-bottom: 1px solid var(--line);\n      }\n\n      .principle-grid {\n        display: grid;\n        grid-template-columns: repeat(3, 1fr);\n        gap: 16px;\n      }\n\n      .principle {\n        min-height: 188px;\n        border: 1px solid var(--line);\n        border-radius: 8px;\n        background: var(--panel);\n        padding: 22px;\n      }\n\n      .principle .number {\n        display: inline-grid;\n        place-items: center;\n        width: 30px;\n        height: 30px;\n        margin-bottom: 16px;\n        border-radius: 8px;\n        background: var(--sage-dark);\n        color: #fff;\n        font-weight: 800;\n      }\n\n      .principle h3 {\n        margin-bottom: 8px;\n        font-size: 19px;\n      }\n\n      .principle p,\n      .object p,\n      .stage p,\n      .question p {\n        color: var(--muted);\n        font-weight: 300;\n        margin-bottom: 0;\n      }\n\n      .pipeline {\n        display: grid;\n        grid-template-columns: repeat(4, minmax(190px, 1fr));\n        gap: 10px;\n        overflow-x: auto;\n        padding-bottom: 6px;\n      }\n\n      .stage {\n        min-height: 230px;\n        border: 1px solid var(--line);\n        border-radius: 8px;\n        background: var(--panel);\n        padding: 14px;\n      }\n\n      .stage h3 {\n        margin-bottom: 9px;\n        font-size: 16px;\n      }\n\n      .stage p {\n        font-size: 13px;\n      }\n\n      .stage .evidence {\n        margin-top: 16px;\n        padding-top: 13px;\n        border-top: 1px solid var(--line);\n        color: var(--quiet);\n        font-size: 12px;\n        font-weight: 720;\n      }\n\n      .stage:nth-child(1) {\n        background: var(--blue-soft);\n      }\n\n      .stage:nth-child(2) {\n        background: var(--gold-soft);\n      }\n\n      .stage:nth-child(3) {\n        background: var(--green-soft);\n      }\n\n      .stage:nth-child(4) {\n        background: var(--clay-soft);\n      }\n\n      .objects-grid {\n        display: grid;\n        grid-template-columns: repeat(4, 1fr);\n        gap: 16px;\n      }\n\n      .object {\n        border: 1px solid var(--line);\n        border-radius: 8px;\n        background: var(--panel);\n        padding: 20px;\n      }\n\n      .object h3 {\n        margin-bottom: 10px;\n        font-size: 20px;\n      }\n\n      .chips {\n        display: flex;\n        flex-wrap: wrap;\n        gap: 8px;\n        margin-top: 18px;\n      }\n\n      .chip {\n        border-radius: 999px;\n        border: 1px solid var(--line);\n        background: #f6f7f4;\n        color: var(--muted);\n        padding: 6px 10px;\n        font-size: 12px;\n        font-weight: 700;\n      }\n\n      .loop {\n        display: grid;\n        gap: 12px;\n        max-width: 820px;\n        margin: 0 auto;\n      }\n\n      .loop-step {\n        display: grid;\n        grid-template-columns: 160px minmax(0, 1fr);\n        gap: 18px;\n        align-items: start;\n        padding: 22px;\n        border: 1px solid var(--line);\n        border-radius: 8px;\n        background: var(--panel);\n      }\n\n      .loop-step h3 {\n        margin-bottom: 8px;\n        font-size: 18px;\n      }\n\n      .loop-step p {\n        color: var(--muted);\n        font-weight: 300;\n        margin-bottom: 0;\n      }\n\n      .capture-grid {\n        display: grid;\n        grid-template-columns: repeat(5, 1fr);\n        gap: 16px;\n      }\n\n      .practice-grid {\n        display: grid;\n        grid-template-columns: repeat(4, 1fr);\n        gap: 16px;\n      }\n\n      .strategy-pair {\n        display: grid;\n        grid-template-columns: repeat(2, minmax(0, 1fr));\n        gap: 16px;\n        margin-bottom: 18px;\n      }\n\n      .strategy-block {\n        border: 1px solid var(--line);\n        border-radius: 8px;\n        background: var(--panel);\n        padding: 22px;\n      }\n\n      .strategy-block h3 {\n        margin-bottom: 10px;\n      }\n\n      .strategy-block p {\n        color: var(--muted);\n        font-weight: 300;\n        margin-bottom: 0;\n      }\n\n      .revenue-flow {\n        display: grid;\n        grid-template-columns: repeat(4, minmax(0, 1fr));\n        border: 1px solid var(--line);\n        border-radius: 8px;\n        background: var(--panel);\n        overflow: hidden;\n      }\n\n      .revenue-step {\n        min-height: 190px;\n        padding: 22px;\n        border-right: 1px solid var(--line);\n      }\n\n      .revenue-step:last-child {\n        border-right: 0;\n      }\n\n      .revenue-step .number {\n        display: grid;\n        place-items: center;\n        width: 32px;\n        height: 32px;\n        margin-bottom: 14px;\n        border-radius: 8px;\n        background: var(--sage-dark);\n        color: #fff;\n        font-weight: 800;\n      }\n\n      .revenue-step h3 {\n        margin-bottom: 8px;\n        font-size: 18px;\n      }\n\n      .revenue-step p {\n        color: var(--muted);\n        font-weight: 300;\n        margin-bottom: 0;\n      }\n\n      .capture,\n      .practice,\n      .strategy {\n        border-radius: 8px;\n        border: 1px solid var(--line);\n        background: var(--panel);\n        padding: 22px;\n      }\n\n      .capture h3,\n      .practice h3,\n      .strategy h3 {\n        margin-bottom: 10px;\n      }\n\n      .capture p,\n      .strategy p {\n        color: var(--muted);\n        font-weight: 300;\n        margin-bottom: 0;\n      }\n\n      .practice ul,\n      .question ul {\n        margin: 16px 0 0;\n        padding-left: 18px;\n        color: var(--muted);\n        font-weight: 300;\n      }\n\n      .practice li,\n      .question li {\n        margin: 8px 0;\n      }\n\n      .callout {\n        border-left: 5px solid var(--clay);\n        background: #fff;\n        padding: 22px 24px;\n        box-shadow: 0 12px 32px rgba(31, 42, 46, 0.08);\n      }\n\n      .callout p {\n        margin-bottom: 0;\n        color: var(--muted);\n        font-size: 19px;\n        font-weight: 300;\n      }\n\n      .split {\n        display: grid;\n        grid-template-columns: minmax(0, 0.88fr) minmax(300px, 0.64fr);\n        gap: 24px;\n        align-items: start;\n      }\n\n      .questions-panel {\n        border: 1px solid var(--line);\n        border-radius: 8px;\n        background: var(--panel);\n        padding: 24px;\n      }\n\n      .question {\n        padding: 18px 0;\n        border-bottom: 1px solid var(--line);\n      }\n\n      .question:first-child {\n        padding-top: 0;\n      }\n\n      .question:last-child {\n        padding-bottom: 0;\n        border-bottom: 0;\n      }\n\n      .question h3 {\n        margin-bottom: 6px;\n        font-size: 18px;\n      }\n\n      details {\n        border: 1px solid var(--line);\n        border-radius: 8px;\n        background: #fff;\n        margin-bottom: 12px;\n      }\n\n      summary {\n        cursor: pointer;\n        padding: 18px 20px;\n        color: var(--sage-dark);\n        font-weight: 800;\n      }\n\n      details p {\n        margin: 0;\n        padding: 0 20px 20px;\n        color: var(--muted);\n        font-weight: 300;\n      }\n\n      footer {\n        padding: 38px 0 54px;\n        color: var(--quiet);\n        border-top: 1px solid var(--line);\n      }\n\n      @media (max-width: 980px) {\n        .hero-grid,\n        .section-head,\n        .split {\n          grid-template-columns: 1fr;\n        }\n\n        .phone {\n          margin: 18px auto 0;\n          max-width: 100%;\n        }\n\n        .principle-grid,\n        .objects-grid,\n        .capture-grid,\n        .practice-grid,\n        .strategy-pair,\n        .revenue-flow {\n          grid-template-columns: 1fr 1fr;\n        }\n\n        .revenue-step:nth-child(2) {\n          border-right: 0;\n        }\n\n        .revenue-step:nth-child(1),\n        .revenue-step:nth-child(2) {\n          border-bottom: 1px solid var(--line);\n        }\n      }\n\n      @media (max-width: 850px) {\n        body {\n          overflow-x: hidden;\n        }\n\n        .shell {\n          width: 100%;\n          padding-right: 14px;\n          padding-left: 14px;\n        }\n\n        .nav {\n          display: none;\n        }\n\n        .hero {\n          padding-top: 42px;\n        }\n\n        h1 {\n          max-width: 100%;\n          font-size: clamp(30px, 8vw, 36px);\n          line-height: 1.04;\n          overflow-wrap: break-word;\n        }\n\n        .hero-copy {\n          max-width: 100%;\n          font-size: 17px;\n          overflow-wrap: break-word;\n        }\n\n        .nowrap {\n          white-space: normal;\n        }\n\n        .hero-actions {\n          align-items: stretch;\n        }\n\n        .button {\n          width: 100%;\n        }\n\n        section {\n          padding: 46px 0;\n        }\n\n        .principle-grid,\n        .objects-grid,\n        .capture-grid,\n        .practice-grid,\n        .strategy-pair,\n        .revenue-flow,\n        .loop {\n          grid-template-columns: 1fr;\n        }\n\n        .revenue-step,\n        .revenue-step:nth-child(2) {\n          border-right: 0;\n          border-bottom: 1px solid var(--line);\n        }\n\n        .revenue-step:last-child {\n          border-bottom: 0;\n        }\n\n        .loop-step {\n          grid-template-columns: 1fr;\n          gap: 8px;\n        }\n\n        .phone-screen {\n          min-height: 584px;\n        }\n      }\n    </style>\n  </head>\n  <body>\n    <header class=\"topbar\">\n      <div class=\"shell topbar-inner\">\n        <div class=\"brand\">\n          <div class=\"mark\">H</div>\n          <span>Hone</span>\n        </div>\n        <nav class=\"nav\" aria-label=\"Page sections\">\n          <a href=\"#model\">Learning Model</a>\n          <a href=\"#objects\">Objects</a>\n          <a href=\"#logging\">Logging</a>\n          <a href=\"#questions\">Questions</a>\n        </nav>\n      </div>\n    </header>\n\n    <main>\n      <section class=\"hero\">\n        <div class=\"shell hero-grid\">\n          <div>\n            <div class=\"eyebrow\">Concept brief</div>\n            <h1>A deliberate practice app for honing grappling skills.</h1>\n            <p class=\"hero-copy\">\n              Hone helps serious grapplers and ambitious hobbyists choose specific skills, train them with intention, and track the evidence that a technique is moving from interesting idea to live, reliable execution.\n            </p>\n          </div>\n\n          <aside class=\"phone\" aria-label=\"Conceptual app mockup\">\n            <div class=\"phone-screen\">\n              <div class=\"phone-status\"></div>\n              <div class=\"app-head\">\n                <div class=\"app-title\">Hone</div>\n                <div class=\"focus-pill\">This week</div>\n              </div>\n              <div class=\"phone-section\">\n                <div class=\"mini-label\">Focus skills</div>\n                <div class=\"skill-card\">\n                  <strong>K guard entry</strong>\n                  <div>Stage: Live</div>\n                  <div class=\"skill-meta\">\n                    <div class=\"metric\"><span>Drill</span><b>90m</b></div>\n                    <div class=\"metric\"><span>Games</span><b>8</b></div>\n                    <div class=\"metric\"><span>Hits</span><b>3</b></div>\n                  </div>\n                </div>\n                <div class=\"skill-card\">\n                  <strong>RNC finish</strong>\n                  <div>Stage: Proven</div>\n                  <div class=\"skill-meta\">\n                    <div class=\"metric\"><span>Drill</span><b>45m</b></div>\n                    <div class=\"metric\"><span>Games</span><b>5</b></div>\n                    <div class=\"metric\"><span>Hits</span><b>11</b></div>\n                  </div>\n                </div>\n              </div>\n              <div class=\"phone-section\">\n                <div class=\"mini-label\">Fast log</div>\n                <div class=\"quick-log\">\n                  <div>Study</div>\n                  <div>Dialogue drill</div>\n                  <div>Constraint game</div>\n                  <div>Rolling</div>\n                </div>\n              </div>\n            </div>\n          </aside>\n        </div>\n      </section>\n\n      <section class=\"band\" id=\"model\">\n        <div class=\"shell\">\n          <div class=\"section-head\">\n            <div>\n              <div class=\"eyebrow\">Top-level idea</div>\n              <h2>The product is built around a skill pipeline.</h2>\n            </div>\n            <p>\n              The app should not try to track all training. It should help grapplers choose specific skills, practice them deliberately, and see which ones are progressing from saved ideas to live execution.\n            </p>\n          </div>\n\n          <div class=\"principle-grid\">\n            <article class=\"principle\">\n              <div class=\"number\">1</div>\n              <h3>Capture the skill</h3>\n              <p>Save the technique, position, transition, finish, escape, or tactical pattern the grappler may want to work on.</p>\n            </article>\n            <article class=\"principle\">\n              <div class=\"number\">2</div>\n              <h3>Train it intentionally</h3>\n              <p>Record the training format: study, dialogue drilling, constraint games, or rolling.</p>\n            </article>\n            <article class=\"principle\">\n              <div class=\"number\">3</div>\n              <h3>Log evidence</h3>\n              <p>Track time, successful executions, partner hit counts, footage, and insights so progress is visible.</p>\n            </article>\n          </div>\n        </div>\n      </section>\n\n      <section>\n        <div class=\"shell\">\n          <div class=\"section-head\">\n            <div>\n              <div class=\"eyebrow\">Proposed stages</div>\n              <h2>Skills move from saved idea to proof under pressure.</h2>\n            </div>\n            <p>\n              Each stage describes where the skill is in the user's acquisition process, from a captured idea to a technique that works repeatedly against meaningful resistance.\n            </p>\n          </div>\n\n          <div class=\"pipeline\" aria-label=\"Skill pipeline stages\">\n            <article class=\"stage\">\n              <h3>Saved</h3>\n              <p>I captured this skill because I may want to work on it later.</p>\n              <div class=\"evidence\">Video, note, source, reason</div>\n            </article>\n            <article class=\"stage\">\n              <h3>Learning</h3>\n              <p>I am actively developing the basic mechanics and procedural understanding needed to perform it.</p>\n              <div class=\"evidence\">Study time, drilling time, cues</div>\n            </article>\n            <article class=\"stage\">\n              <h3>Live</h3>\n              <p>I can create or recognize the conditions for the skill and execute it against resistance.</p>\n              <div class=\"evidence\">Game time, rolling hits, partner hit counts</div>\n            </article>\n            <article class=\"stage\">\n              <h3>Proven</h3>\n              <p>I can hit it repeatedly on strong partners, including people who know my game or are hard to catch.</p>\n              <div class=\"evidence\">Best-partner proof, confidence</div>\n            </article>\n          </div>\n        </div>\n      </section>\n\n      <section id=\"objects\">\n        <div class=\"shell\">\n          <div class=\"section-head\">\n            <div>\n              <div class=\"eyebrow\">Information architecture</div>\n              <h2>The app has four core objects.</h2>\n            </div>\n          </div>\n\n          <div class=\"objects-grid\">\n            <article class=\"object\">\n              <h3>Skill</h3>\n              <p>A specific thing the user wants to acquire.</p>\n              <div class=\"chips\">\n                <span class=\"chip\">Stage</span>\n                <span class=\"chip\">Resources</span>\n                <span class=\"chip\">Notes</span>\n                <span class=\"chip\">Targets</span>\n              </div>\n            </article>\n            <article class=\"object\">\n              <h3>Session</h3>\n              <p>A class, open mat, private, or competition training day.</p>\n              <div class=\"chips\">\n                <span class=\"chip\">Date</span>\n                <span class=\"chip\">Journal</span>\n                <span class=\"chip\">Focus review</span>\n              </div>\n            </article>\n            <article class=\"object\">\n              <h3>Training Block</h3>\n              <p>A chunk of work inside a session tied to one skill.</p>\n              <div class=\"chips\">\n                <span class=\"chip\">Type</span>\n                <span class=\"chip\">Duration</span>\n                <span class=\"chip\">Executions</span>\n                <span class=\"chip\">Insights</span>\n              </div>\n            </article>\n            <article class=\"object\">\n              <h3>Partner</h3>\n              <p>A person the user has successfully executed a skill against.</p>\n              <div class=\"chips\">\n                <span class=\"chip\">Hit list</span>\n                <span class=\"chip\">Skill counts</span>\n                <span class=\"chip\">Last hit</span>\n              </div>\n            </article>\n          </div>\n        </div>\n      </section>\n\n      <section class=\"band\">\n        <div class=\"shell\">\n          <div class=\"section-head\">\n            <div>\n              <div class=\"eyebrow\">Skill capture</div>\n              <h2>Skills can start from a reference, an idea, or a training goal.</h2>\n            </div>\n            <p>\n              Creating a skill should be fast: name the thing the user wants to work on, attach anything useful, and drop it into the pipeline.\n            </p>\n          </div>\n\n          <div class=\"capture-grid\">\n            <article class=\"capture\">\n              <h3>Blank Skill</h3>\n              <p>Create a skill manually from an idea, coach suggestion, or training goal.</p>\n            </article>\n            <article class=\"capture\">\n              <h3>YouTube</h3>\n              <p>Save a video as a reference and attach notes, cues, or timestamps.</p>\n            </article>\n            <article class=\"capture\">\n              <h3>Instagram</h3>\n              <p>Capture a reel or post before it disappears into saved-content clutter.</p>\n            </article>\n            <article class=\"capture\">\n              <h3>Reference Video</h3>\n              <p>Attach any video that helps the user understand what good execution looks like.</p>\n            </article>\n            <article class=\"capture\">\n              <h3>Quick Note</h3>\n              <p>Save a thought after training and turn it into a skill later.</p>\n            </article>\n          </div>\n        </div>\n      </section>\n\n      <section id=\"logging\">\n        <div class=\"shell\">\n          <div class=\"section-head\">\n            <div>\n              <div class=\"eyebrow\">Logging model</div>\n              <h2>The app tracks four types of training.</h2>\n            </div>\n            <p>\n              For each skill, users can log study, dialogue drilling, constraint games, and rolling. Each training type uses its own metrics: time, successful executions, partner hits, footage, and insights where they apply.\n            </p>\n          </div>\n\n          <div class=\"practice-grid\">\n            <article class=\"practice\">\n              <h3>Study</h3>\n              <p>Watching, reading, reviewing footage, or thinking through the skill away from live practice.</p>\n              <ul>\n                <li>Track time</li>\n                <li>Save resources</li>\n                <li>Capture insights</li>\n              </ul>\n            </article>\n            <article class=\"practice\">\n              <h3>Dialogue Drilling</h3>\n              <p>Cooperative exploration and mechanical refinement.</p>\n              <ul>\n                <li>Track time</li>\n                <li>Capture cues</li>\n                <li>Capture insights</li>\n              </ul>\n            </article>\n            <article class=\"practice\">\n              <h3>Constraint Games</h3>\n              <p>Live situational work / task-based rounds / CLA games.</p>\n              <ul>\n                <li>Track time</li>\n                <li>Track successful executions</li>\n                <li>Capture hits on partners and insights</li>\n              </ul>\n            </article>\n            <article class=\"practice\">\n              <h3>Rolling</h3>\n              <p>Open live training where the exchange can go anywhere.</p>\n              <ul>\n                <li>Track successful executions</li>\n                <li>Add partners to the hit list</li>\n                <li>Capture time and insights where useful</li>\n              </ul>\n            </article>\n          </div>\n        </div>\n      </section>\n\n      <section class=\"band\">\n        <div class=\"shell\">\n          <div class=\"section-head\">\n            <div>\n              <div class=\"eyebrow\">User loop</div>\n              <h2>The app should guide pre-training intention and post-training reflection.</h2>\n            </div>\n            <p>\n              This turns Hone from a passive tracker into a deliberate practice companion.\n            </p>\n          </div>\n\n          <div class=\"loop\">\n            <article class=\"loop-step\">\n              <h3>Set Intention</h3>\n              <p>Before training, pick one to three focus skills for the day or week.</p>\n            </article>\n            <article class=\"loop-step\">\n              <h3>Train</h3>\n              <p>Use those skills in study, drilling, games, and rolling.</p>\n            </article>\n            <article class=\"loop-step\">\n              <h3>Log Evidence</h3>\n              <p>After training, record time, successful executions, footage, hit counts, and insights.</p>\n            </article>\n            <article class=\"loop-step\">\n              <h3>Refine Focus</h3>\n              <p>Update the stage, next cue, or next training intention based on evidence.</p>\n            </article>\n          </div>\n        </div>\n      </section>\n\n      <section>\n        <div class=\"shell\">\n          <div class=\"section-head\">\n            <div>\n              <div class=\"eyebrow\">Product strategy</div>\n              <h2>Distribution starts with a tool pros actually use.</h2>\n            </div>\n            <p>\n              The app has to be useful enough that pros would use it in their own training. If that is true, their normal training process can become content, and that content can become a recurring income stream.\n            </p>\n          </div>\n\n          <div class=\"strategy-pair\">\n            <article class=\"strategy-block\">\n              <h3>Why pros would use it</h3>\n              <p>Hone should make deliberate practice easier for people who already care deeply about improving: choose the skill, log the work, preserve insights, review footage, and track whether the skill is becoming reliable.</p>\n            </article>\n            <article class=\"strategy-block\">\n              <h3>What makes hobbyists use it</h3>\n              <p>For hobbyists, the usage risk is habit inertia: most people are used to showing up, taking class, and doing whatever training gives them that day. Borrowed status helps overcome that inertia because using the same tool as a pro makes deliberate practice feel like part of the pro identity they want to emulate.</p>\n            </article>\n          </div>\n\n          <div class=\"revenue-flow\" aria-label=\"Pro revenue pipeline\">\n            <article class=\"revenue-step\">\n              <div class=\"number\">1</div>\n              <h3>Use the app</h3>\n              <p>The pro uses Hone for an activity they already do: deciding what to work on, training it, logging evidence, and reflecting afterward.</p>\n            </article>\n            <article class=\"revenue-step\">\n              <div class=\"number\">2</div>\n              <h3>Make content</h3>\n              <p>That use becomes easy content: what skill they are honing, how they are practicing it, what changed, and what they learned.</p>\n            </article>\n            <article class=\"revenue-step\">\n              <div class=\"number\">3</div>\n              <h3>Audience signs up</h3>\n              <p>The pro already has an audience. Viewers see Hone in use, want to train more deliberately, and subscribe through the pro's affiliate link.</p>\n            </article>\n            <article class=\"revenue-step\">\n              <div class=\"number\">4</div>\n              <h3>Earn recurring revenue</h3>\n              <p>The pro gets a healthy percentage of monthly revenue from their users. A second level could pay them when athletes they recruit generate subscribers too.</p>\n            </article>\n          </div>\n        </div>\n      </section>\n\n      <section id=\"questions\">\n        <div class=\"shell split\">\n          <div>\n            <div class=\"eyebrow\">For expert review</div>\n            <h2>Questions to pressure-test with a high-level learner.</h2>\n            <p class=\"lead\">\n              These questions should test the learning model, the logging burden, and whether the app solves real problems for serious practitioners.\n            </p>\n          </div>\n\n          <aside class=\"questions-panel\">\n            <div class=\"question\">\n              <h3>What problems do pros already have?</h3>\n              <ul>\n                <li>What do serious competitors and coaches need to track in training?</li>\n                <li>Where are their current tools weak?</li>\n                <li>What would make deliberate practice easier for people who already train deliberately?</li>\n                <li>What would make the app worth opening before and after training?</li>\n                <li>What would they consider noise?</li>\n              </ul>\n            </div>\n            <div class=\"question\">\n              <h3>Should the pipeline stages be refined?</h3>\n              <ul>\n                <li>Are Saved, Learning, Live, and Proven good enough stages to start with?</li>\n                <li>Is Live too broad?</li>\n                <li>Should the Live phase be broken into quantified resistance levels, such as 1-10?</li>\n                <li>Can users rate resistance consistently enough for that to be useful?</li>\n                <li>Should skills move automatically based on evidence, or should users move them based on their own assessment?</li>\n              </ul>\n            </div>\n            <div class=\"question\">\n              <h3>How should progress be quantified?</h3>\n              <ul>\n                <li>Which metrics actually indicate skill acquisition?</li>\n                <li>When is time trained meaningful?</li>\n                <li>When are successful executions meaningful?</li>\n                <li>Should partner quality matter?</li>\n                <li>Is confidence or self-assessment reliable enough to use?</li>\n              </ul>\n            </div>\n            <div class=\"question\">\n              <h3>What is the minimum useful logging flow?</h3>\n              <ul>\n                <li>What can be logged in under 30 seconds after training?</li>\n                <li>Which fields are essential versus non-essential?</li>\n                <li>Which fields would become annoying?</li>\n                <li>Should voice notes be the default for insights?</li>\n                <li>How much structure helps before it starts feeling like homework?</li>\n              </ul>\n            </div>\n          </aside>\n        </div>\n      </section>\n\n      <section>\n        <div class=\"shell\">\n          <div class=\"section-head\">\n            <div>\n              <div class=\"eyebrow\">Later possibilities</div>\n              <h2>Expandable, but not required for the first version.</h2>\n            </div>\n            <p>\n              These are powerful directions, but each should wait until the core learning loop is working.\n            </p>\n          </div>\n\n          <details>\n            <summary>AI-assisted reflection</summary>\n            <p>Convert voice notes into concise summaries: what worked, what failed, next cue, and next training intention.</p>\n          </details>\n          <details>\n            <summary>Eco games library</summary>\n            <p>A searchable library of constraint games connected to specific skills, positions, and learning goals.</p>\n          </details>\n          <details>\n            <summary>Starter templates for skills</summary>\n            <p>Offer lightweight starting points for common skill goals so users can begin with useful cues, drills, logging fields, and progress markers instead of a blank skill card.</p>\n          </details>\n          <details>\n            <summary>Collaboration</summary>\n            <p>Let coaches or training partners suggest skills, add notes, share games, or review progress.</p>\n          </details>\n          <details>\n            <summary>Coaching add-on</summary>\n            <p>Give athletes and coaches a way to assign skills, review student training footage, comment on executions, and monetize coaching relationships inside the same skill pipeline.</p>\n          </details>\n          <details>\n            <summary>External databases</summary>\n            <p>Potential integrations with resources like BJJ Mental Models DB or OutlierDB if they support the learning loop.</p>\n          </details>\n        </div>\n      </section>\n    </main>\n\n    <footer>\n      <div class=\"shell\">\n        Hone concept brief. Built to clarify the learning model before building the product.\n      </div>\n    </footer>\n  </body>\n</html>\n";export default{async fetch(request){const url=new URL(request.url);if(url.pathname!=="/"&&url.pathname!=="/index.html"){url.pathname="/";url.search="";return Response.redirect(url.toString(),302)}return new Response(html,{headers:{"content-type":"text/html; charset=utf-8","cache-control":"public, max-age=300"}})}};